type Checkout = {
  id: number;
  customer: { email: string; country: string };
  shipping: { method: 'standard' | 'express'; address: { line1: string; city: string } };
  lines: { sku: string; quantity: number }[];
  onSubmit: () => void;
};

type MyAwaited<T> = T extends Promise<infer V> ? MyAwaited<V> : T;

type DeepReadonly<T> = T extends (...args: any[]) => any
  ? T
  : T extends object
    ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
    : T;

type DeepPartial<T> = T extends readonly unknown[]
  ? T
  : T extends object
    ? { [K in keyof T]?: DeepPartial<T[K]> }
    : T;

const defaultCheckout: Checkout = {
  id: 1042,
  customer: { email: 'mona@example.com', country: 'EG' },
  shipping: { method: 'standard', address: { line1: '12 Nile St', city: 'Cairo' } },
  lines: [{ sku: 'TENT-2P', quantity: 1 }],
  onSubmit: () => {},
};

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function mergeDeep(base: Record<string, unknown>, overrides: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = { ...base };
  for (const [key, value] of Object.entries(overrides)) {
    if (value === undefined) continue;
    const current = out[key];
    out[key] = isPlainObject(current) && isPlainObject(value) ? mergeDeep(current, value) : value;
  }
  return out;
}

function checkoutFixture(overrides: DeepPartial<Checkout> = {}): Checkout {
  // mergeDeep works on untyped records; the result has Checkout's shape by construction.
  return mergeDeep(defaultCheckout, overrides as Record<string, unknown>) as Checkout;
}

